-- Candidate only. Not a migration until generated by Supabase CLI and tested.
-- Run as migration owner in a single transaction; no production execution yet.
LOCK TABLE public.groups, public.schedule_assignments IN ACCESS EXCLUSIVE MODE;
DO $preflight$
BEGIN
  IF EXISTS (SELECT 1 FROM public.groups
    WHERE year_of_admission IS NULL OR degree_id IS NULL OR letter IS NULL
      OR btrim(letter) = '' OR letter <> upper(btrim(letter))) THEN
    RAISE EXCEPTION 'Group identity needs reviewed cleanup before migration';
  END IF;
  IF EXISTS (SELECT 1 FROM public.groups GROUP BY year_of_admission, upper(btrim(letter)), degree_id HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'Normalized group identities collide';
  END IF;
  IF EXISTS (SELECT 1 FROM public.schedule_assignments s LEFT JOIN public.groups g ON g.id=s.group_id
    WHERE s.group_id IS NOT NULL AND g.id IS NULL) THEN
    RAISE EXCEPTION 'Orphan group references exist';
  END IF;
END;
$preflight$;

ALTER TABLE public.groups
  ALTER COLUMN year_of_admission SET NOT NULL,
  ALTER COLUMN degree_id SET NOT NULL,
  ALTER COLUMN letter SET NOT NULL,
  ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(),
  ADD COLUMN version integer NOT NULL DEFAULT 1,
  ADD COLUMN archived_at timestamptz,
  ADD COLUMN archived_by uuid,
  ADD CONSTRAINT groups_letter_canonical_check CHECK (letter <> '' AND letter = upper(btrim(letter))),
  ADD CONSTRAINT groups_version_positive_check CHECK (version > 0),
  ADD CONSTRAINT groups_archive_metadata_check CHECK ((archived_at IS NULL) = (archived_by IS NULL));

-- Production inspection found no index beginning with group_id.
CREATE INDEX schedule_assignments_group_id_idx ON public.schedule_assignments(group_id);

CREATE SCHEMA group_admin_private;
REVOKE ALL ON SCHEMA group_admin_private FROM PUBLIC, anon, authenticated;
CREATE TABLE group_admin_private.events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  group_id bigint NOT NULL,
  actor_id uuid NOT NULL,
  action text NOT NULL CHECK (action IN ('create','edit','archive','reactivate','delete')),
  occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  before_state jsonb,
  after_state jsonb,
  reason text CHECK (reason IS NULL OR (char_length(btrim(reason)) BETWEEN 1 AND 500 AND reason = btrim(reason))),
  CONSTRAINT group_events_shape_check CHECK (
    (action='create' AND before_state IS NULL AND after_state IS NOT NULL) OR
    (action='delete' AND before_state IS NOT NULL AND after_state IS NULL) OR
    (action IN ('edit','archive','reactivate') AND before_state IS NOT NULL AND after_state IS NOT NULL)
  ),
  CONSTRAINT group_events_reason_check CHECK (action NOT IN ('archive','reactivate','delete') OR reason IS NOT NULL)
);
ALTER TABLE group_admin_private.events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE group_admin_private.events FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA group_admin_private FROM PUBLIC, anon, authenticated;
CREATE INDEX group_events_group_time_idx ON group_admin_private.events(group_id, occurred_at DESC, id DESC);

-- Intentionally no FK from audit group_id to groups: events survive deletion.
-- Keep existing group uniqueness and schedule FK unchanged.
-- This file is NOT deployable alone: lifecycle functions, creation normalization,
-- audit triggers, grant hardening and schedule guards are mandatory before release.
